#include "core/ProjectStorage.hpp"
namespace prismkey::core { std::filesystem::path ProjectStorage::destination(StorageKind kind,const std::filesystem::path& source){ const char* folder=kind==StorageKind::PublicKey?"keys/public":kind==StorageKind::PrivateKey?"keys/private":"signatures"; return std::filesystem::current_path()/folder/source.filename(); } bool ProjectStorage::copy(StorageKind kind,const std::filesystem::path& source,bool overwrite){ std::error_code ec; auto target=destination(kind,source); std::filesystem::create_directories(target.parent_path(),ec); if(ec||(!overwrite&&std::filesystem::exists(target))) return false; std::filesystem::copy_file(source,target,overwrite?std::filesystem::copy_options::overwrite_existing:std::filesystem::copy_options::none,ec); return !ec; } }
